            console.log("Reserve amount %s", amount0Out);
            uint256 borrowXST = amount0Out * balance / uniswapETHBalance;
            console.log("Swap xst %s", borrowXST);
            Uni_Pair_V2(UniswapV20x694f).swap(borrowXST, 0, address(this), "00");
